import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.jar.*;
import java.util.regex.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.objectweb.asm.*;
import org.objectweb.asm.commons.*;

/** Build-only bytecode isolation. No generated bytecode enters the formal source tree. */
public final class ComposeBuildTools {
    static String relocate(String name) {
        if (name.startsWith("androidx/graphics/path/")) return name;
        if (name.startsWith("androidx/")) return "com/icar03/compose/" + name;
        if (name.startsWith("android/support/")) return "com/icar03/compose/" + name;
        return name;
    }
    static final Remapper MAPPER = new Remapper() {
        @Override public String map(String name) { return relocate(name); }
        @Override public Object mapValue(Object value) {
            if (value instanceof String) {
                String s = (String) value;
                if (s.equals("androidx.graphics.path")) return s;
                if (s.startsWith("androidx.") || s.startsWith("android.support.")) return relocate(s.replace('.', '/')).replace('/', '.');
                if (s.startsWith("androidx/") || s.startsWith("android/support/")) return relocate(s);
                // Kotlin Metadata type signatures are strings, not JVM descriptors.
                if (s.startsWith("Landroidx/") || s.startsWith("Landroid/support/")) return "L" + relocate(s.substring(1));
            }
            return super.mapValue(value);
        }
    };
    public static void main(String[] args) throws Exception {
        switch (args[0]) {
            case "relocate": relocateJar(Paths.get(args[1]), Paths.get(args[2])); break;
            case "manifest": manifestInfo(Paths.get(args[1])); break;
            case "stubs": smaliLibrary(Paths.get(args[1]), Paths.get(args[2])); break;
            case "stable": stableIds(Paths.get(args[1]), Paths.get(args[2])); break;
            case "rjava": generateR(Paths.get(args[1]), Paths.get(args[2]), args[3], Paths.get(args[4])); break;
            default: throw new IllegalArgumentException("Unknown build tool mode");
        }
    }
    static void relocateJar(Path input, Path output) throws Exception {
        Set<String> entries = new HashSet<>();
        try (JarFile jar = new JarFile(input.toFile()); JarOutputStream out = new JarOutputStream(Files.newOutputStream(output))) {
            Enumeration<JarEntry> list = jar.entries();
            while (list.hasMoreElements()) {
                JarEntry item = list.nextElement();
                if (item.isDirectory() || item.getName().endsWith(".SF") || item.getName().endsWith(".RSA") || item.getName().endsWith("module-info.class") || item.getName().startsWith("META-INF/versions/")) continue;
                if (!item.getName().endsWith(".class") && !item.getName().startsWith("META-INF/services/")) continue;
                String name = item.getName();
                byte[] data = jar.getInputStream(item).readAllBytes();
                if (name.endsWith(".class")) {
                    ClassReader reader = new ClassReader(data);
                    ClassWriter writer = new ClassWriter(0);
                    ClassVisitor annotations = new ClassVisitor(Opcodes.ASM9, new ClassRemapper(writer, MAPPER)) {
                        @Override public AnnotationVisitor visitAnnotation(String descriptor, boolean visible) {
                            return descriptor.startsWith("Landroidx/compose/ui/tooling/preview/") || descriptor.equals("Lorg/codehaus/mojo/animal_sniffer/IgnoreJRERequirement;") ? null : super.visitAnnotation(descriptor, visible);
                        }
                        @Override public MethodVisitor visitMethod(int access, String method, String descriptor, String signature, String[] exceptions) {
                            return new MethodVisitor(Opcodes.ASM9, super.visitMethod(access, method, descriptor, signature, exceptions)) {
                                @Override public AnnotationVisitor visitAnnotation(String desc, boolean visible) {
                                    return desc.startsWith("Landroidx/compose/ui/tooling/preview/") || desc.equals("Lorg/codehaus/mojo/animal_sniffer/IgnoreJRERequirement;") ? null : super.visitAnnotation(desc, visible);
                                }
                            };
                        }
                    };
                    reader.accept(annotations, 0);
                    data = writer.toByteArray();
                    name = relocate(name.substring(0, name.length() - 6)) + ".class";
                } else if (name.startsWith("META-INF/services/")) {
                    String service = name.substring("META-INF/services/".length());
                    name = "META-INF/services/" + (service.startsWith("androidx.") ? "com.icar03.compose." + service : service);
                    data = new String(data, java.nio.charset.StandardCharsets.UTF_8).replace("androidx.", "com.icar03.compose.androidx.").getBytes(java.nio.charset.StandardCharsets.UTF_8);
                }
                if (!entries.add(name)) throw new IllegalStateException("Relocation duplicate " + name);
                JarEntry target = new JarEntry(name); target.setTime(0); out.putNextEntry(target); out.write(data); out.closeEntry();
            }
        }
    }
    static void manifestInfo(Path file) throws Exception {
        Document doc=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(file.toFile());
        String pkg=doc.getDocumentElement().getAttribute("package");
        NodeList sdk=doc.getElementsByTagName("uses-sdk");
        String minimum=sdk.getLength()==0?"1":((Element)sdk.item(0)).getAttribute("android:minSdkVersion");
        System.out.println(pkg+"\n"+(minimum.isEmpty()?"1":minimum));
    }
    static int flags(String words) {
        int bits=0;
        for(String word:(words==null?"":words).trim().split("\\s+")) switch(word) {
            case "public": bits|=Opcodes.ACC_PUBLIC;break; case "private":bits|=Opcodes.ACC_PRIVATE;break;
            case "protected":bits|=Opcodes.ACC_PROTECTED;break; case "static":bits|=Opcodes.ACC_STATIC;break;
            case "final":bits|=Opcodes.ACC_FINAL;break; case "interface":bits|=Opcodes.ACC_INTERFACE;break;
            case "abstract":bits|=Opcodes.ACC_ABSTRACT;break; case "native":bits|=Opcodes.ACC_NATIVE;break;
            case "synthetic":bits|=Opcodes.ACC_SYNTHETIC;break; case "bridge":bits|=Opcodes.ACC_BRIDGE;break;
            case "annotation":bits|=Opcodes.ACC_ANNOTATION;break; case "enum":bits|=Opcodes.ACC_ENUM;break;
            case "volatile":bits|=Opcodes.ACC_VOLATILE;break; case "transient":bits|=Opcodes.ACC_TRANSIENT;break;
            case "synchronized":bits|=Opcodes.ACC_SYNCHRONIZED;break; case "varargs":bits|=Opcodes.ACC_VARARGS;break;
        }
        return bits;
    }
    static String internal(String descriptor) { return descriptor.substring(1,descriptor.length()-1); }
    static void smaliLibrary(Path source, Path output) throws Exception {
        List<Path> files;
        try (java.util.stream.Stream<Path> tree=Files.walk(source)) {
            files=tree.filter(p->p.toString().endsWith(".smali") && source.relativize(p).getName(0).toString().matches("smali(?:_classes\\d+)?")).sorted().toList();
        }
        Set<String> classNames=new HashSet<>();
        try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(output))) {
            for(Path file:files) {
                List<String> lines=Files.readAllLines(file);
                String name=null, parent="java/lang/Object";int access=0;List<String> interfaces=new ArrayList<>();
                for(String line:lines) {
                    Matcher c=Pattern.compile("^\\.class (?:(.*?) )?(L[^;]+;)$").matcher(line);
                    if(c.matches()){access=flags(c.group(1));name=internal(c.group(2));}
                    if(line.startsWith(".super "))parent=internal(line.substring(7).trim());
                    if(line.startsWith(".implements "))interfaces.add(internal(line.substring(12).trim()));
                }
                if(name==null)throw new IllegalStateException("Missing Smali class "+file);
                if(!classNames.add(name))throw new IllegalStateException("Duplicate original Smali class "+name);
                ClassWriter writer=new ClassWriter(0);
                writer.visit(Opcodes.V1_8,access,name,null,parent,interfaces.toArray(new String[0]));
                for(String line:lines) {
                    Matcher method=Pattern.compile("^\\.method (?:(.*?) )?([^ ]+)(\\(.*)$").matcher(line);
                    if(method.matches()) {
                        int methodAccess=flags(method.group(1));String descriptor=method.group(3);
                        MethodVisitor mv=writer.visitMethod(methodAccess,method.group(2),descriptor,null,null);
                        if((methodAccess&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0) {
                            mv.visitCode();mv.visitInsn(Opcodes.ACONST_NULL);mv.visitInsn(Opcodes.ATHROW);
                            int locals=(methodAccess&Opcodes.ACC_STATIC)==0?1:0;
                            for(Type arg:Type.getArgumentTypes(descriptor))locals+=arg.getSize();
                            mv.visitMaxs(1,locals);
                        }
                        mv.visitEnd();
                    }
                    Matcher field=Pattern.compile("^\\.field (?:(.*?) )?([^ :]+):([^ ]+)(?: .*)?$").matcher(line);
                    if(field.matches())writer.visitField(flags(field.group(1)),field.group(2),field.group(3),null,null).visitEnd();
                }
                writer.visitEnd();JarEntry entry=new JarEntry(name+".class");entry.setTime(0);out.putNextEntry(entry);out.write(writer.toByteArray());out.closeEntry();
            }
        }
        System.out.println("Original Smali ABI library: "+files.size()+" classes; library-only, never injected");
    }
    static void stableIds(Path xml, Path output) throws Exception {
        Document doc = DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(xml.toFile());
        NodeList nodes = doc.getElementsByTagName("public");
        List<String> lines = new ArrayList<>();
        for (int i = 0; i < nodes.getLength(); i++) {
            Element e = (Element) nodes.item(i);
            lines.add("com.autonavi.amapautolite:" + e.getAttribute("type") + "/" + e.getAttribute("name") + " = " + e.getAttribute("id"));
        }
        Files.write(output, lines);
    }
    static Map<String, String> symbols(Path file) throws Exception {
        Map<String, String> result = new LinkedHashMap<>();
        for (String line : Files.readAllLines(file)) {
            String[] p = line.split(" ", 4);
            if (p.length == 4) result.put(p[1] + "/" + p[2], p[3]);
        }
        return result;
    }
    static void generateR(Path full, Path own, String pkg, Path output) throws Exception {
        Map<String, String> merged = symbols(full), original = symbols(own);
        Map<String, List<String>> groups = new TreeMap<>();
        for (Map.Entry<String, String> entry : original.entrySet()) {
            String type = entry.getKey().split("/", 2)[0];
            String name = entry.getKey().split("/", 2)[1];
            String value;
            String javaType = "int";
            if (type.equals("styleable") && entry.getValue().startsWith("{")) {
                javaType = "int[]";
                String[] old = entry.getValue().replace("{", "").replace("}", "").trim().split(",\\s*");
                String[] global = Optional.ofNullable(merged.get(entry.getKey())).orElseThrow(() -> new IllegalStateException("Missing styleable " + entry.getKey())).replace("{", "").replace("}", "").trim().split(",\\s*");
                String[] mapped = new String[old.length];
                for (Map.Entry<String, String> index : original.entrySet()) {
                    if (index.getKey().startsWith("styleable/" + name + "_") && !index.getValue().startsWith("{")) {
                        int ownIndex = Integer.decode(index.getValue());
                        int globalIndex = Integer.decode(Optional.ofNullable(merged.get(index.getKey())).orElseThrow(() -> new IllegalStateException("Missing index " + index.getKey())));
                        mapped[ownIndex] = global[globalIndex];
                    }
                }
                for (int i = 0; i < mapped.length; i++) if (mapped[i] == null) throw new IllegalStateException("Unmapped styleable " + name + " index " + i);
                value = "{ " + String.join(", ", mapped) + " }";
            } else if (type.equals("styleable")) {
                // AAR bytecode may inline this index; preserve its original ordering.
                value = entry.getValue();
            } else value = Optional.ofNullable(merged.get(entry.getKey())).orElseThrow(() -> new IllegalStateException("Missing resource " + entry.getKey()));
            groups.computeIfAbsent(type, k -> new ArrayList<>()).add("public static " + javaType + " " + name + " = " + value + ";");
        }
        StringBuilder source = new StringBuilder("package " + pkg + ";\npublic final class R {\n");
        for (Map.Entry<String, List<String>> type : groups.entrySet()) {
            source.append("public static final class ").append(type.getKey()).append(" {\n");
            type.getValue().forEach(line -> source.append(line).append('\n'));
            source.append("}\n");
        }
        source.append("}\n");
        Path destination = output.resolve(pkg.replace('.', '/')).resolve("R.java");
        Files.createDirectories(destination.getParent()); Files.writeString(destination, source);
    }
}
